            success: false,
            error: `Session is awaiting a multi-choice answer (waiting_choice), not an approval. Use mesh_answer_question with promptId "${heldPrompt.promptId}" instead of mesh_approve.`,
            waitingChoice: true,
            promptId: heldPrompt.promptId
